window.kbPageData["views/entry/k-5d9a5cd789e2855c"] = {"key":"entry/k-5d9a5cd789e2855c","state":{"route":"entry/k-5d9a5cd789e2855c"},"node":{"id":"k-5d9a5cd789e2855c","mode":"k","title":"湿地的二氧化碳、甲烷和氨气排放","type":"原理与机制","domain":"生态环境","reading":"","intro":"","priority":100,"aliases":["湿地碳释放以二氧化碳和甲烷为主"],"qs":["江苏 2024 C类 行测#11"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"湿地可通过生物呼吸和有机质分解释放二氧化碳，积水缺氧时还可由微生物产生甲烷。氨挥发是氮循环过程，部分湿地在一定条件下也会向大气释放氨气。","review":{"definition":"湿地可通过生物呼吸和有机质分解释放二氧化碳，积水缺氧时还可由微生物产生甲烷。氨挥发是氮循环过程，部分湿地在一定条件下也会向大气释放氨气。","explanation":"本题要求选出不正确项，参考答案为C。解析所说的二氧化碳和甲烷是湿地向大气释放碳的主要气体，这一判断无法排除氨排放。施氮稻田可发生氨挥发，天然潮汐盐沼的观测也表明，低潮时更多土壤裸露，氨排放可增大。C项未限定湿地类型和条件，按“湿地可以排放这些气体”理解，不能据此将C判为唯一错误项。","references":[{"source":"web-e4306d21be164793","location":"Abstract，低潮氨通量观测","quote":"The largest fluxes were observed at low tide when more soil was exposed."},{"source":"web-ec60025d93c602dd","location":"首页摘要及关键词","quote":"稻田  氨挥发  施氮量"}],"evidence":"碳释放以二氧化碳和甲烷为主","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"江苏 2024 C类 行测#11":{"paper":"江苏 2024 C类 行测","n":11,"mod":"常识判断","src":["3f1ec77ae8a18519b57e.pdf",2],"asrc":["02d6b49839583bdaf297.pdf",4],"card":"d0daf295cce3a7c256cae646","links":[{"id":"k-5d9a5cd789e2855c","role":"直接考查","why":"湿地固定的碳可经呼吸或微生物分解重新释放，这一机制解释了湿地的二氧化碳和甲烷排放。"}]}},"terms":{},"references":{"web-e4306d21be164793":{"name":"Atmospheric Ammonia Measurements Over a Coastal Salt Marsh Ecosystem Along the Mid-Atlantic U.S.","url":"https://agupubs.onlinelibrary.wiley.com/doi/10.1029/2019JG005522"},"web-ec60025d93c602dd":{"name":"《中国生态农业学报》稻田氨挥发田间试验","url":"https://www.ecoagri.ac.cn/cn/article/pdf/preview/10.3724/SP.J.1011.2011.00032.pdf"}},"topics":[],"units":{"k-5d9a5cd789e2855c":[["江苏 2024 C类 行测#11"]]}};
